mapper.select:
SELECT s.device_id AS deviceId, s.device_code AS deviceCode, s.sensor_type AS sensorType, s.sensor_name AS sensorName, s.value AS value, s.unit AS unit, s.data_time AS dataTime, s.quality_flag AS qualityFlag FROM agri_prod_sensor_data s WHERE s.tenant_id = #{tenantId} AND s.sensor_type IN ('temperature','humidity')
AND s.plot_id = #{plotId} AND s.farm_id = #{farmId}
AND s.farm_id = #{farmId} AND s.id = (SELECT x.id FROM agri_prod_sensor_data x WHERE x.tenant_id = s.tenant_id AND x.device_id = s.device_id AND x.sensor_type = s.sensor_type AND x.sensor_name <=> s.sensor_name AND x.farm_id <=> s.farm_id AND x.plot_id <=> s.plot_id ORDER BY x.data_time DESC, x.id DESC LIMIT 1) ORDER BY s.data_time DESC, s.id DESC

SELECT * FROM agri_prod_sensor_data
WHERE tenant_id = #{tenantId} AND device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
ORDER BY data_time DESC

SELECT DATE_FORMAT(data_time, '%Y-%m-%d %H:00:00') AS hour,
       ROUND(AVG(value), 4) AS avgValue,
       COUNT(*) AS sampleCount
FROM agri_prod_sensor_data
WHERE tenant_id = #{tenantId} AND device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
GROUP BY DATE_FORMAT(data_time, '%Y-%m-%d %H:00:00')
ORDER BY hour

SELECT COUNT(*) AS dataCount,
       ROUND(AVG(value), 4) AS avgValue,

       ROUND(MAX(value), 4) AS `maxValue`,
       ROUND(MIN(value), 4) AS `minValue`,
       MAX(data_time) AS latestTime
FROM agri_prod_sensor_data
WHERE tenant_id = #{tenantId} AND device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
